1	/**
2	 * VR-1: the machine contract of `nexus verify`: the verdicts, the process exit codes and the JSON document `--json`
3	 * prints (the same document `--receipt <file>` writes). docs/USER_MANUAL.md documents the exit codes from the table
4	 * below and test/verify_command.test.ts fails when the manual falls behind. The types are plain data (no functions, no
5	 * index signatures) so a schema can be generated from them, as scripts/gen_run_result_schema.mjs does for `nexus run`.
6	 */
7	import type { EngineeringOutcome, VerificationEvidence } from "./core/turn.js";
8	import type { EvidenceOutcomeReason } from "./core/verification_outcome.js";
9	
10	/**
11	 * Version of the document `nexus verify --json` prints. Adding an optional member keeps the version; removing or
12	 * renaming a member, or changing a member's type or meaning, bumps it.
13	 */
14	export const VERIFY_RESULT_SCHEMA_VERSION = 1;
15	
16	/**
17	 * VERIFIED: evidence independent of the change shows it. REGRESSION_FREE: the tests pass, which shows only that nothing
18	 * they cover broke. UNVERIFIED: nothing was established (see `outcome` and `reason`). BLOCKED: a person must decide
19	 * before anything is run or concluded.
20	 */
21	export type VerifyVerdict = "VERIFIED" | "REGRESSION_FREE" | "UNVERIFIED" | "BLOCKED";
22	
23	/** Why the verdict is not VERIFIED: the outcome ladder's reasons, and the ones only `nexus verify` gives. */
24	export type VerifyReason =
25	  | EvidenceOutcomeReason
26	  /** Base and head are the same tree. */
27	  | "NOTHING_TO_VERIFY"
28	  /** The head changed the files that define the verifier, so the verifier was not run on the head. */
29	  | "VERIFIER_DEFINITION_CHANGED"
30	  /** The verifier is an inline program whose definition cannot be captured, so it was not run on the head. */
31	  | "VERIFIER_DEFINITION_NOT_CAPTURED"
32	  /** A type-check project the agent would enforce applies, and this version does not run type-checks. */
33	  | "TYPECHECK_NOT_RUN"
34	  /** A verifier discovered in the repository needs the operator's approval. */
35	  | "VERIFIER_NOT_APPROVED"
36	  /** Git was refused in the checkout (a planted or rewritten `.git`). */
37	  | "UNTRUSTED_CHECKOUT"
38	  /** A tree is larger than the limits, or reading it took longer than allowed. */
39	  | "TREE_LIMIT_EXCEEDED"
40	  /** A tree holds something that is not materialised (a submodule). */
41	  | "UNSUPPORTED_TREE"
42	  /** `nexus verify` itself failed; nothing was established. */
43	  | "INTERNAL_ERROR";
44	
45	export interface VerifyExitCode {
46	  code: number;
47	  name: string;
48	  when: string;
49	}
50	
51	/**
52	 * Every exit code of `nexus verify`, one row per condition (the same row shape as RUN_EXIT_CODES). A code can appear in
53	 * several rows: the exit code alone does not tell those conditions apart, the JSON document does. The "Exit codes"
54	 * table in docs/USER_MANUAL.md is this table. Unlike `nexus run`, code 3 exists (a person must decide) and an empty
55	 * change is not 0 (the caller chose the base).
56	 */
57	export const VERIFY_EXIT_CODES = [
58	  { code: 0, name: "verified", when: "`VERIFIED`: the change is shown by evidence independent of it." },
59	  { code: 1, name: "failed", when: "`UNVERIFIED` with outcome `NOT_ESTABLISHED`: the verifier failed or timed out on the head, or the head changed the verifier's own definition so it was not run." },
60	  { code: 1, name: "error", when: "`UNVERIFIED` with reason `INTERNAL_ERROR`: `nexus verify` itself could not finish, so nothing was established." },
61	  { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs; no JSON document)." },
62	  { code: 2, name: "unverified", when: "`REGRESSION_FREE` (the tests pass without showing the change), or `UNVERIFIED` because there is no verifier, no test executed, base and head are the same tree, or an enforced type-check applies that this version does not run." },
63	  { code: 2, name: "usage", when: "A usage error: not a Git working tree, a base or head that does not name a commit, or an invalid option value or combination." },
64	  { code: 3, name: "blocked", when: "`BLOCKED`: a person must decide. The discovered verifier is not approved, the checkout is not trusted, or a tree exceeds the limits or holds a submodule." },
65	  { code: 130, name: "interrupted", when: "Interrupted (SIGINT or SIGTERM). The signal is acted on when the running verifier process ends; a second signal exits at once and may leave no JSON document." },
66	] as const satisfies readonly VerifyExitCode[];
67	
68	export type VerifyExitName = (typeof VERIFY_EXIT_CODES)[number]["name"];
69	
70	export function verifyExitCode(name: VerifyExitName): number {
71	  return VERIFY_EXIT_CODES.find((row) => row.name === name)!.code;
72	}
73	
74	/** The verdict and exit-code row of every reason. A new reason does not compile until both are decided. */
75	export const VERIFY_REASONS: Record<VerifyReason, { verdict: Exclude<VerifyVerdict, "VERIFIED">; exit: VerifyExitName }> = {
76	  REGRESSION_FREE: { verdict: "REGRESSION_FREE", exit: "unverified" },
77	  NO_APPLICABLE_VERIFIER: { verdict: "UNVERIFIED", exit: "unverified" },
78	  NO_TESTS_EXECUTED: { verdict: "UNVERIFIED", exit: "unverified" },
79	  VERIFICATION_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
80	  NOTHING_TO_VERIFY: { verdict: "UNVERIFIED", exit: "unverified" },
81	  TYPECHECK_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
82	  VERIFIER_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
83	  VERIFIER_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
84	  VERIFIER_DEFINITION_CHANGED: { verdict: "UNVERIFIED", exit: "failed" },
85	  VERIFIER_DEFINITION_NOT_CAPTURED: { verdict: "UNVERIFIED", exit: "failed" },
86	  INTERNAL_ERROR: { verdict: "UNVERIFIED", exit: "error" },
87	  VERIFIER_NOT_APPROVED: { verdict: "BLOCKED", exit: "blocked" },
88	  UNTRUSTED_CHECKOUT: { verdict: "BLOCKED", exit: "blocked" },
89	  TREE_LIMIT_EXCEEDED: { verdict: "BLOCKED", exit: "blocked" },
90	  UNSUPPORTED_TREE: { verdict: "BLOCKED", exit: "blocked" },
91	};
92	
93	/** The verdict for a reason; no reason is VERIFIED. */
94	export function verifyVerdictFor(reason: VerifyReason | undefined): VerifyVerdict {
95	  return reason === undefined ? "VERIFIED" : VERIFY_REASONS[reason].verdict;
96	}
97	
98	/** The exit-code row for a reason; no reason is VERIFIED. */
99	export function verifyExitNameFor(reason: VerifyReason | undefined): VerifyExitName {
100	  return reason === undefined ? "verified" : VERIFY_REASONS[reason].exit;
101	}
102	
103	/** One side of the comparison. */
104	export interface VerifyTreeRef {
105	  /** What the operator named: a ref, or "(working tree)". */
106	  ref: string;
107	  /** The commit; null for the working tree, which has none. */
108	  commit: string | null;
109	  /** The Git tree that was materialised and verified. For the working tree: tracked and untracked files that are not ignored, as `git add -A` would stage them (Nexus's own `.nexus` state left out). */
110	  tree: string;
111	  workingTree: boolean;
112	}
113	
114	export interface VerifyVerifierRecord {
115	  command: string;
116	  /** `configured`: the operator's `--verifier`. `discovered`: selected from the files of the base tree. */
117	  source: "configured" | "discovered";
118	  /** The base-tree file that justifies a discovered verifier, or "configured". */
119	  evidence: string;
120	  /** sha256 of the command and the script body it resolves to in the base tree. */
121	  digest: string;
122	  /** How it was approved: it is the operator's own command, `--yes`, a matching `--approve-verifier` digest, or not at all. */
123	  approval: "operator_command" | "yes" | "digest" | "none";
124	  /** The script body the command resolves to in the base tree (capped), when there is one. */
125	  script?: string;
126	}
127	
128	export interface VerifyRunRecord {
129	  /** `base_tests_on_head`: the test files as they were on the base, run against the head's code. */
130	  phase: "base" | "head" | "base_tests_on_head";
131	  passed: boolean;
132	  timedOut: boolean;
133	  /** Null when the process was killed or never started. */
134	  exitCode: number | null;
135	  /** The output shows at least one test that ran. */
136	  executedTests: boolean;
137	  outputSha256: string;
138	  outputTruncated: boolean;
139	  durationMs: number;
140	  /** The end of the output of a run that did not pass: repository-controlled text, redacted and capped. */
141	  outputTail?: string;
142	}
143	
144	export interface VerifyBaselineSummary {
145	  /** The verifier failed on the base tree. */
146	  failed: boolean;
147	  /** The base run can serve as the "failed before" half: it failed, by itself, with tests that ran. */
148	  usable: boolean;
149	  /** Test files captured from the base tree; null when one was too large to capture. */
150	  testFiles: number | null;
151	  /** The files that define the verifier were captured from the base tree. */
152	  verifierDefinitionBound: boolean;
153	  /** Why they could not be captured. */
154	  verifierUnbindableReason?: string;
155	}
156	
157	/** An ingredient of the verdict that this version does not run. Later versions add statuses and members. */
158	export interface VerifyIngredient {
159	  status: "NOT_RUN";
160	  detail?: string;
161	}
162	
163	export interface VerifyLimits {
164	  /** Deadline of each verifier run, in seconds. */
165	  timeoutSecs: number;
166	  maxTreeFiles: number;
167	  maxTreeBytes: number;
168	}
169	
170	/** Printed when verification reached a verdict, whatever the verdict. It is also the receipt. */
171	export interface VerifyJsonResult {
172	  /** Version of this document's schema. Always the first member. */
173	  schema_version: typeof VERIFY_RESULT_SCHEMA_VERSION;
174	  verdict: VerifyVerdict;
175	  outcome: Exclude<EngineeringOutcome, "NOT_REQUIRED">;
176	  /** Absent only when the verdict is VERIFIED. */
177	  reason?: VerifyReason;
178	  detail?: string;
179	  /** The process exit code. */
180	  exitCode: number;
181	  /** Absent when the checkout was refused before anything was resolved. */
182	  base?: VerifyTreeRef;
183	  head?: VerifyTreeRef;
184	  /** Paths that differ between base and head (at most 200 are listed). */
185	  changedFiles: string[];
186	  changedFileCount: number;
187	  /** Absent when no verifier applies. */
188	  verifier?: VerifyVerifierRecord;
189	  /** The operator-declared deliverable files. */
190	  deliverables: string[];
191	  /** Every verifier process that ran, in order. */
192	  runs: VerifyRunRecord[];
193	  baseline?: VerifyBaselineSummary;
194	  /** The evidence the outcome was derived from. */
195	  verification?: VerificationEvidence;
196	  typecheck: VerifyIngredient;
197	  guard: VerifyIngredient;
198	  review: VerifyIngredient;
199	  /** Dependency directories of the caller's checkout that were linked into both scratch trees. */
200	  linkedDependencyDirs: string[];
201	  limits: VerifyLimits;
202	  /** Names (never values) of verdict-affecting environment variables that were set. */
203	  environment: string[];
204	  nexusVersion: string;
205	  startedAt: string;
206	  durationMs: number;
207	}
208	
209	/** Printed instead of a result when no verdict was reached: a usage error or an interruption. */
210	export interface VerifyJsonError {
211	  /** Version of this document's schema. Always the first member. */
212	  schema_version: typeof VERIFY_RESULT_SCHEMA_VERSION;
213	  error: string;
214	  /** The process exit code. */
215	  exitCode: number;
216	}
217	
218	/** The one JSON document `nexus verify --json` writes to stdout. A result has `verdict`; an error document does not. */
219	export type VerifyJsonOutput = VerifyJsonResult | VerifyJsonError;
220

