1	/**
2	 * VR-1: `nexus verify`, the verdict on a change that Nexus did not necessarily make: a working tree against a commit,
3	 * or one commit against another. No model is involved.
4	 *
5	 * Both sides are materialised into scratch directories (the caller's checkout is never written), the verifier is taken
6	 * from the operator or discovered in the BASE tree (the head is the change under test and cannot choose its own judge),
7	 * it is run on the base and on the head, and the outcome is derived by the same rules the agent applies to its own
8	 * work: this module re-composes captureChangeBaselineImpl / judgeIndependenceImpl (core/completion_oracle.ts) and the
9	 * evidence built in core/spine_handlers.ts, and derives the outcome with outcomeFromEvidence.
10	 *
11	 * Authority: the request names only what to compare. Everything that can raise the verdict (the verifier command, its
12	 * approval, the declared deliverables, the deadline) comes from the operator context. Anything that cannot be fully
13	 * evaluated lowers the verdict with a reason that names it; nothing here raises one.
14	 */
15	import fs from "node:fs";
16	import os from "node:os";
17	import path from "node:path";
18	import { createHash } from "node:crypto";
19	import { getBuildIdentity } from "../build_identity.js";
20	import { trustedGitArgs } from "../git.js";
21	import {
22	  SKIP_DIRS, describeVerifier, discoverTypechecks, discoverVerifier, hasExecutedTests, isFilteredVerifierCommand, isVerifierDeliverableBound,
23	  runVerifierShell, typecheckMode, verifierTimeoutSecs,
24	} from "../tester.js";
25	import { formatDiagnosticForOutput, safeTerminal } from "../ui.js";
26	import {
27	  VERIFY_RESULT_SCHEMA_VERSION, verifyExitCode, verifyExitNameFor, verifyVerdictFor,
28	  type VerifyJsonResult, type VerifyReason, type VerifyRunRecord, type VerifyTreeRef, type VerifyVerifierRecord,
29	} from "../verify_contract.js";
30	import { GitError, UntrustedCheckoutError, git, printable } from "../worktrunk/git.js";
31	import {
32	  isInlineProgramVerifier, judgeWithoutCopy, prepareBaselineTestsCopy, requiresWorkspaceVerifierDefinitionBinding, snapshotTests,
33	  snapshotVerifierDefinitionWithReason, testsChangedSince, verifierDefinitionChangedSince, type ChangeBaseline, type Independence,
34	} from "./independent_check.js";
35	import type { VerificationEvidence } from "./turn.js";
36	import { outcomeFromEvidence } from "./verification_outcome.js";
37	
38	/** What to compare. Nothing here can raise the verdict, so this is the part a remote caller may supply. */
39	export interface VerifyRequest {
40	  /** The top of a Git working tree. */
41	  worktree: string;
42	  /** The commit the change starts from (default `HEAD`). */
43	  base?: string;
44	  /** The commit that holds the change; absent to verify the working tree. */
45	  head?: string;
46	}
