48	/** What only the operator (the launcher's command line) decides. */
49	export interface VerifyOperatorContext {
50	  /** The operator's own verifier command; absent to discover one in the base tree. */
51	  verifierCommand?: string;
52	  /** Approve whatever verifier is discovered (`--yes`). */
53	  approveDiscoveredVerifier?: boolean;
54	  /** Approve the discovered verifier with exactly this digest (`--approve-verifier`). */
55	  approvedVerifierDigest?: string;
56	  /** Workspace-relative product files the change is meant to deliver. */
57	  deliverables?: readonly string[];
58	  /** Deadline of each verifier run in seconds (default: NEXUS_VERIFIER_TIMEOUT_SECS, else 300). */
59	  timeoutSecs?: number;
60	  /** Aborted to interrupt: acted on between child processes. */
