66	/** The request or the options cannot be acted on: not a working tree, a ref that names no commit, a bad path. */
67	export class VerifyUsageError extends Error {
68	  constructor(message: string) {
69	    super(message);
70	    this.name = "VerifyUsageError";
71	  }
72	}
