81	/** Largest tree materialised: files and total bytes. A larger tree is BLOCKED, never verified in part. */
82	export const VERIFY_MAX_TREE_FILES = 20_000;
83	export const VERIFY_MAX_TREE_BYTES = 512 * 1024 * 1024;
84	/** Deadline of each Git command that reads or writes a whole tree, and of each small one. */
85	const GIT_TREE_TIMEOUT_MS = 120_000;
86	const GIT_TIMEOUT_MS = 30_000;
87	const GIT_LISTING_BUFFER = 64 * 1024 * 1024;
88	/** Dependency directories of the caller's checkout linked into the scratch trees, so both sides run with the same installed packages. */
89	const DEPENDENCY_DIRS: readonly string[] = ["node_modules", "vendor", ".venv", "venv"];
90	const MAX_DEPENDENCY_LINKS = 64;
91	const MAX_DEPENDENCY_SCAN = 2000;
92	const MAX_LISTED_CHANGES = 200;
93	const WORKING_TREE = "(working tree)";
94	/** Variables that can change the verdict or what the verifier sees: their NAMES are recorded when set. */
95	export const VERIFY_RECORDED_ENVIRONMENT: readonly string[] = ["NEXUS_TRUST_WORKSPACE", "NEXUS_TYPECHECK", "NEXUS_VERIFIER_TIMEOUT_SECS", "NEXUS_VERIFIER_ENV_PASSTHROUGH"];
96	
97	/** Ends verification early with a verdict that is not VERIFIED. */
98	class Stop extends Error {
99	  constructor(readonly reason: VerifyReason, readonly detail: string) {
100	    super(detail);
101	  }
102	}
