104	// Scratch directories still on disk. Removed in verifyChange's `finally`; the exit hook covers a process.exit() in between.
105	const liveScratch = new Set<string>();
106	let exitHook = false;
107	function removeScratch(dir: string): void {
108	  try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* reported by the caller's leak, not fatal here */ }
109	  liveScratch.delete(dir);
110	}
111	function makeScratch(): string {
112	  if (!exitHook) {
113	    exitHook = true;
114	    process.on("exit", () => { for (const dir of [...liveScratch]) removeScratch(dir); });
115	  }
116	  // Resolved: the snapshot functions compare real paths with the workspace root, and a temp directory can sit behind a link.
117	  const dir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-verify-")));
118	  liveScratch.add(dir);
119	  return dir;
120	}
121	
122	const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
123	const capped = (text: string, max: number) => (text.length > max ? `${text.slice(0, max)}…` : text);
124	
125	function validRef(ref: string): boolean {
126	  return ref.length > 0 && ref.length <= 256 && !ref.startsWith("-") && !/[\0\r\n]/.test(ref);
127	}
128	
129	/** A declared deliverable as a normalised workspace-relative path; a path that is absolute or leaves the tree is refused. */
130	function normaliseDeliverable(file: string): string {
131	  const normal = path.posix.normalize(file.trim().replace(/\\/g, "/")).replace(/^\.\//, "");
132	  if (!normal || normal === "." || normal.startsWith("../") || normal === ".." || path.isAbsolute(normal) || /[\0\r\n]/.test(normal)) {
133	    throw new VerifyUsageError(`--deliverable-file ${printable(file)} is not a path inside the working tree`);
134	  }
135	  return normal;
136	}
137	
138	/** Whether `relative` below `root` is reached through real directories only (no link on the way). */
139	function realDirectoryInside(root: string, relative: string): boolean {
140	  let cursor = root;
141	  for (const part of relative.split(path.sep).filter(Boolean)) {
142	    cursor = path.join(cursor, part);
143	    try {
144	      if (!fs.lstatSync(cursor).isDirectory()) return false;
145	    } catch {
146	      return false;
147	    }
148	  }
149	  return true;
150	}
