152	/**
153	 * Links the caller's dependency directories (those the trees do not hold themselves) into every scratch tree, so base
154	 * and head run with the same installed packages. Bounded; links in the caller's checkout are not followed.
155	 */
156	function linkDependencyDirs(worktree: string, targets: readonly string[]): string[] {
157	  const linked: string[] = [];
158	  let scanned = 0;
159	  const walk = (relative: string, depth: number) => {
160	    if (depth > 3 || linked.length >= MAX_DEPENDENCY_LINKS) return;
161	    let entries: fs.Dirent[];
162	    try { entries = fs.readdirSync(path.join(worktree, relative), { withFileTypes: true }); } catch { return; }
163	    for (const entry of entries) {
164	      if (++scanned > MAX_DEPENDENCY_SCAN || linked.length >= MAX_DEPENDENCY_LINKS) return;
165	      if (!entry.isDirectory()) continue;
166	      const child = path.join(relative, entry.name);
167	      if (DEPENDENCY_DIRS.includes(entry.name)) {
168	        let used = false;
169	        for (const target of targets) {
170	          const destination = path.join(target, child);
171	          if (!realDirectoryInside(target, relative)) continue;
172	          try { fs.lstatSync(destination); continue; } catch { /* the tree has nothing there: link it */ }
173	          fs.symlinkSync(path.join(worktree, child), destination, "dir");
174	          used = true;
175	        }
176	        if (used) linked.push(child.split(path.sep).join("/"));
177	      } else if (!SKIP_DIRS.has(entry.name)) {
178	        walk(child, depth + 1);
179	      }
180	    }
181	  };
182	  walk("", 0);
183	  return linked.sort();
184	}
