186	/**
187	 * The verdict on the change from `request.base` to `request.head` (or to the working tree). Returns a result for every
188	 * ending that has a verdict, including a refusal and an internal error; throws VerifyUsageError for a request that
189	 * cannot be acted on and VerifyInterrupted when the signal aborted. Scratch directories are removed on every path.
190	 */
191	export async function verifyChange(request: VerifyRequest, operator: VerifyOperatorContext = {}): Promise<VerifyJsonResult> {
192	  const started = Date.now();
193	  const timeoutSecs = verifierTimeoutSecs(operator.timeoutSecs);
194	  const deliverables = [...new Set((operator.deliverables ?? []).map(normaliseDeliverable))];
195	  const progress = (message: string) => operator.onProgress?.(message);
196	  // Child processes run synchronously: yielding here is what lets a signal handler run between them.
197	  const checkpoint = async () => {
198	    await new Promise<void>((resolve) => setImmediate(resolve));
199	    if (operator.signal?.aborted) throw new VerifyInterrupted();
200	  };
201	
202	  const doc: Omit<VerifyJsonResult, "schema_version" | "verdict" | "outcome" | "reason" | "detail" | "exitCode" | "durationMs"> = {
203	    changedFiles: [],
204	    changedFileCount: 0,
205	    deliverables,
206	    runs: [],
207	    typecheck: { status: "NOT_RUN", detail: "this version of nexus verify does not run type-checks" },
208	    guard: { status: "NOT_RUN", detail: "this version of nexus verify does not classify edits to verification files" },
209	    review: { status: "NOT_RUN", detail: "this version of nexus verify has no reviewer" },
210	    linkedDependencyDirs: [],
211	    limits: { timeoutSecs, maxTreeFiles: VERIFY_MAX_TREE_FILES, maxTreeBytes: VERIFY_MAX_TREE_BYTES },
212	    environment: VERIFY_RECORDED_ENVIRONMENT.filter((name) => Boolean(process.env[name])),
213	    nexusVersion: getBuildIdentity().string,
214	    startedAt: new Date(started).toISOString(),
215	  };
216	  const finish = (outcome: VerifyJsonResult["outcome"], reason: VerifyReason | undefined, detail: string | undefined): VerifyJsonResult => {
217	    const { base, head, ...rest } = doc;
218	    return {
219	      schema_version: VERIFY_RESULT_SCHEMA_VERSION,
220	      verdict: verifyVerdictFor(reason),
221	      outcome,
222	      ...(reason === undefined ? {} : { reason }),
223	      ...(detail ? { detail: capped(safeTerminal(detail), 600) } : {}),
224	      exitCode: verifyExitCode(verifyExitNameFor(reason)),
225	      ...(base ? { base } : {}),
226	      ...(head ? { head } : {}),
227	      ...rest,
228	      durationMs: Date.now() - started,
229	    };
230	  };
231	
232	  let worktree: string;
233	  try {
234	    worktree = fs.realpathSync(request.worktree);
235	    if (!fs.statSync(worktree).isDirectory()) throw new Error("not a directory");
236	  } catch {
237	    throw new VerifyUsageError(`${printable(request.worktree)} is not a directory`);
238	  }
239	  const baseRef = request.base ?? "HEAD";
240	  if (!validRef(baseRef)) throw new VerifyUsageError(`--base ${printable(baseRef.slice(0, 80))} is not a valid revision name`);
241	  if (request.head !== undefined && !validRef(request.head)) throw new VerifyUsageError(`--head ${printable(request.head.slice(0, 80))} is not a valid revision name`);
242	
243	  let scratch: string | undefined;
244	  try {
245	    // The checkout itself must be one Git can be run in (a planted or rewritten `.git` is refused).
246	    trustedGitArgs(worktree);
247	
248	    let gitEnvironment: Record<string, string> = {};
249	    const run = (args: string[], options: { env?: Record<string, string>; timeoutMs?: number } = {}) => {
250	      const timeoutMs = options.timeoutMs ?? GIT_TIMEOUT_MS;
251	      let result;
252	      try {
253	        result = git(worktree, args, { allowFailure: true, timeoutMs, maxBuffer: GIT_LISTING_BUFFER, env: { ...gitEnvironment, ...(options.env ?? {}) } });
254	      } catch (error) {
255	        if (error instanceof GitError && /ENOBUFS/.test(error.message)) throw new Stop("TREE_LIMIT_EXCEEDED", `the output of git ${args[0]} is larger than ${GIT_LISTING_BUFFER} bytes`);
256	        throw error;
257	      }
258	      if (result.timedOut) throw new Stop("TREE_LIMIT_EXCEEDED", `git ${args[0]} did not finish within ${timeoutMs / 1000}s`);
259	      return result;
260	    };
261	    const must = (args: string[], options: { env?: Record<string, string>; timeoutMs?: number } = {}): string => {
262	      const result = run(args, options);
263	      if (result.status !== 0) throw new Error(`git ${args[0]} failed: ${printable(result.stderr.trim().split("\n")[0] ?? "").slice(0, 300) || `exit ${result.status}`}`);
264	      return result.stdout.replace(/\n$/, "");
265	    };
266	
267	    const top = run(["rev-parse", "--show-toplevel"]);
268	    if (top.status !== 0) throw new VerifyUsageError(`${printable(worktree)} is not a Git working tree`);
269	    if (fs.realpathSync(top.stdout.replace(/\n$/, "")) !== worktree) {
270	      throw new VerifyUsageError(`${printable(worktree)} is inside a Git working tree but is not its top (${printable(top.stdout.trim())}); pass the top with --worktree`);
271	    }
272	    const resolveCommit = (option: string, ref: string): { commit: string; tree: string } => {
273	      const commit = run(["rev-parse", "--verify", "--quiet", "--end-of-options", `${ref}^{commit}`]);
274	      if (commit.status !== 0 || !/^[0-9a-f]{40,64}$/.test(commit.stdout.trim())) throw new VerifyUsageError(`${option} ${printable(ref)} does not name a commit in this repository`);
275	      return { commit: commit.stdout.trim(), tree: must(["rev-parse", "--verify", `${commit.stdout.trim()}^{tree}`]) };
276	    };
277	    const base = resolveCommit("--base", baseRef);
278	    const headCommit = request.head === undefined ? undefined : resolveCommit("--head", request.head);
279	
280	    scratch = makeScratch();
281	    const baseDir = path.join(scratch, "base");
282	    const headDir = path.join(scratch, "head");
283	    // Objects written while reading the working tree go to a scratch object directory; the repository's own is read-only here.
284	    const scratchObjects = path.join(scratch, "objects");
285	    fs.mkdirSync(scratchObjects);
286	    gitEnvironment = { GIT_OBJECT_DIRECTORY: scratchObjects, GIT_ALTERNATE_OBJECT_DIRECTORIES: path.resolve(worktree, must(["rev-parse", "--git-path", "objects"])) };
287	
288	    await checkpoint();
289	    let headTree: string;
290	    const headIndex = { GIT_INDEX_FILE: path.join(scratch, "head.index") };
291	    if (headCommit) {
292	      headTree = headCommit.tree;
293	    } else {
294	      // The working tree as `git add -A` would stage it, staged into a scratch index and scratch objects. Bounded
295	      // before anything is read: the listing, then each file's size.
296	      const listed = new Set(must(["ls-files", "-z", "--cached", "--others", "--exclude-standard"], { timeoutMs: GIT_TREE_TIMEOUT_MS }).split("\0").filter((name) => name && name !== ".nexus" && !name.startsWith(".nexus/")));
297	      if (listed.size > VERIFY_MAX_TREE_FILES) throw new Stop("TREE_LIMIT_EXCEEDED", `the working tree has ${listed.size} files that are not ignored (limit ${VERIFY_MAX_TREE_FILES})`);
298	      let bytes = 0;
299	      for (const name of listed) {
300	        try {
301	          const stat = fs.lstatSync(path.join(worktree, name));
302	          if (stat.isFile()) bytes += stat.size;
303	        } catch { /* deleted in the working tree */ }
304	        if (bytes > VERIFY_MAX_TREE_BYTES) throw new Stop("TREE_LIMIT_EXCEEDED", `the working tree's files that are not ignored are larger than ${VERIFY_MAX_TREE_BYTES} bytes`);
305	      }
306	      if (run(["rev-parse", "--verify", "--quiet", "HEAD^{commit}"]).status === 0) must(["read-tree", "HEAD"], { env: headIndex });
307	      must(["add", "-A", "--", ":/", ":(top,exclude).nexus"], { env: headIndex, timeoutMs: GIT_TREE_TIMEOUT_MS });
308	      headTree = must(["write-tree"], { env: headIndex });
309	    }
310	    doc.base = { ref: baseRef, commit: base.commit, tree: base.tree, workingTree: false };
311	    doc.head = headCommit
312	      ? { ref: request.head!, commit: headCommit.commit, tree: headTree, workingTree: false }
313	      : { ref: WORKING_TREE, commit: null, tree: headTree, workingTree: true };
314	
315	    if (base.tree === headTree) {
316	      return finish("UNVERIFIED", "NOTHING_TO_VERIFY", `base and head are the same tree (${headTree.slice(0, 12)}): there is no change to verify`);
317	    }
318	    const changed = must(["diff-tree", "-r", "--no-renames", "--name-only", "-z", base.tree, headTree], { timeoutMs: GIT_TREE_TIMEOUT_MS }).split("\0").filter(Boolean);
319	    doc.changedFileCount = changed.length;
320	    doc.changedFiles = changed.slice(0, MAX_LISTED_CHANGES).map((file) => printable(file));
321	
322	    /** Refuses a tree that is over the limits or holds a submodule, then writes it to `directory` from a scratch index. */
323	    const materialise = (tree: string, directory: string, label: string, index: Record<string, string>, indexReady: boolean) => {
324	      let files = 0;
325	      let bytes = 0;
326	      for (const record of must(["ls-tree", "-r", "-l", "-z", tree], { timeoutMs: GIT_TREE_TIMEOUT_MS }).split("\0")) {
327	        if (!record) continue;
328	        const tab = record.indexOf("\t");
329	        const [mode, , , size] = record.slice(0, tab).split(/\s+/);
330	        if (mode === "160000") throw new Stop("UNSUPPORTED_TREE", `the ${label} tree holds a submodule (${record.slice(tab + 1)}); submodules are not materialised, so the tree cannot be verified as a whole`);
331	        files++;
332	        bytes += Number(size) || 0;
333	        if (files > VERIFY_MAX_TREE_FILES) throw new Stop("TREE_LIMIT_EXCEEDED", `the ${label} tree has more than ${VERIFY_MAX_TREE_FILES} files`);
334	        if (bytes > VERIFY_MAX_TREE_BYTES) throw new Stop("TREE_LIMIT_EXCEEDED", `the ${label} tree is larger than ${VERIFY_MAX_TREE_BYTES} bytes`);
335	      }
336	      if (!indexReady) must(["read-tree", tree], { env: index });
337	      fs.mkdirSync(directory);
338	      must(["checkout-index", "-a", `--prefix=${directory}${path.sep}`], { env: index, timeoutMs: GIT_TREE_TIMEOUT_MS });
339	    };
340	    progress(`materialising base ${base.commit.slice(0, 12)} and head ${headCommit ? headCommit.commit.slice(0, 12) : WORKING_TREE}`);
341	    materialise(base.tree, baseDir, "base", { GIT_INDEX_FILE: path.join(scratch, "base.index") }, false);
342	    await checkpoint();
343	    materialise(headTree, headDir, "head", headIndex, !headCommit);
344	    doc.linkedDependencyDirs = linkDependencyDirs(worktree, [baseDir, headDir]);
345	    // Read now, before any repository code runs in these trees.
346	    const typecheckProjects = [...discoverTypechecks(headDir), ...discoverTypechecks(baseDir)];
347	    await checkpoint();
348	
349	    // ---- The verifier: the operator's, or the one the BASE tree defines. The head never chooses it. ----
350	    const configured = operator.verifierCommand?.trim() || undefined;
351	    const source: "configured" | "discovered" = configured ? "configured" : "discovered";
352	    const description = describeVerifier(baseDir, configured);
353	    if (!description) {
354	      const atHead = discoverVerifier(headDir);
355	      const evidence: VerificationEvidence = { status: "NO_APPLICABLE_VERIFIER", at: new Date().toISOString() };
356	      doc.verification = evidence;
357	      const derived = outcomeFromEvidence(evidence);
358	      return finish(derived.outcome, derived.reason, `the base tree defines no verifier${atHead ? ` (the head defines ${atHead.command}, but the head is the change under test and cannot choose its own verifier)` : ""}; give one with --verifier`);
