360	    const command = description.command;
361	    const approval: VerifyVerifierRecord["approval"] = configured
362	      ? "operator_command"
363	      : operator.approveDiscoveredVerifier
364	        ? "yes"
365	        : operator.approvedVerifierDigest !== undefined && operator.approvedVerifierDigest.trim().toLowerCase() === description.digest
366	          ? "digest"
367	          : "none";
368	    doc.verifier = {
369	      command: safeTerminal(command),
370	      source,
371	      evidence: safeTerminal(description.evidence),
372	      digest: description.digest,
373	      approval,
374	      ...(description.script !== undefined && description.script !== command ? { script: capped(safeTerminal(description.script), 2000) } : {}),
