380	    }
381	
382	    const execute = async (phase: VerifyRunRecord["phase"], directory: string) => {
383	      await checkpoint();
384	      progress(`running ${command} (${phase === "base" ? "base" : phase === "head" ? "head" : "base tests against head code"})`);
385	      const begun = Date.now();
386	      const ran = runVerifierShell(command, directory, timeoutSecs * 1000);
387	      const executedTests = hasExecutedTests(ran.output);
388	      doc.runs.push({
389	        phase,
390	        passed: ran.success,
391	        timedOut: ran.timedOut,
392	        exitCode: ran.exitCode,
393	        executedTests,
394	        outputSha256: sha256(ran.output),
395	        outputTruncated: ran.truncated,
396	        durationMs: Date.now() - begun,
397	        ...(ran.success ? {} : { outputTail: safeTerminal(ran.output.slice(-2000)) }),
398	      });
399	      await checkpoint();
400	      return { ...ran, executedTests };
401	    };
402	
403	    // ---- The baseline (completion_oracle.ts captureChangeBaselineImpl): the base run and the base tree's tests and verifier definition. ----
404	    // The snapshots are taken before the run, so nothing the verifier writes into its tree is mistaken for the base.
405	    const tests = snapshotTests(baseDir);
406	    const definition = snapshotVerifierDefinitionWithReason(baseDir, command, deliverables);
407	    const baseRun = await execute("base", baseDir);
408	    const baseline: ChangeBaseline = {
409	      command,
410	      failed: !baseRun.success,
411	      tests,
412	      // verifierDefinitionAtCaptureImpl: an inline program is never excused as "unbindable".
413	      ...(definition.verifier || isInlineProgramVerifier(command) ? { verifier: definition.verifier } : { verifier: null, verifierUnbindableReason: definition.reason }),
414	      trustedDeliverables: deliverables,
415	      at: new Date().toISOString(),
416	    };
417	    // A base run that did not fail by itself with tests that ran is no "failed before": the command was missing (126,
418	    // 127), it was killed or timed out, or nothing shows a test ran.
419	    const baseUnusable = !baseRun.success && (baseRun.timedOut || baseRun.exitCode === null || baseRun.exitCode === 126 || baseRun.exitCode === 127 || !baseRun.executedTests);
