421	      failed: baseline.failed,
422	      usable: baseline.failed && !baseUnusable,
423	      testFiles: tests ? tests.size : null,
424	      verifierDefinitionBound: Boolean(baseline.verifier?.size),
425	      ...(baseline.verifierUnbindableReason ? { verifierUnbindableReason: baseline.verifierUnbindableReason } : {}),
426	    };
427	
428	    // ---- The head (spine_handlers.ts, the completion oracle) ----
429	    const bindsWorkspaceDefinition = source === "discovered" || requiresWorkspaceVerifierDefinitionBinding(command);
430	    const unboundDetail = bindsWorkspaceDefinition && !baseline.verifier?.size && baseline.verifierUnbindableReason
431	      ? `the verifier's definition could not be bound (${baseline.verifierUnbindableReason}), so it was not verified unchanged (the candidate could have edited it) and the pass is regression evidence only`
432	      : undefined;
433	    if (bindsWorkspaceDefinition && !unboundDetail && verifierDefinitionChangedSince(headDir, baseline)) {
434	      const captured = Boolean(baseline.verifier?.size);
435	      const detail = captured
436	        ? `the head changes a file that defines the verifier (${command}) or that the base's tests import and that is not a declared deliverable, so the verifier was not run on the head: its output could not establish verification${deliverables.length ? "" : ". If the changed file is the product under test, declare it with --deliverable-file"}`
