438	      const evidence: VerificationEvidence = {
439	        status: "FAILED", command, source, exitSuccess: false, hasExecutedTests: false, isDeliverableBound: false, independent: false, independenceDetail: detail, at: new Date().toISOString(),
440	      };
441	      doc.verification = evidence;
442	      // The ladder's reason here is VERIFIER_FAILED; the verifier did not run, so the reason says what happened instead.
443	      return finish(outcomeFromEvidence(evidence).outcome, captured ? "VERIFIER_DEFINITION_CHANGED" : "VERIFIER_DEFINITION_NOT_CAPTURED", detail);
444	    }
445	
446	    const headRun = await execute("head", headDir);
447	    // The head's own code has now run in headDir and could have rewritten it (restored a test it weakened, patched the
448	    // product). Everything judged from here on reads a second, untouched copy of the head tree.
449	    const headPristine = path.join(scratch, "head-pristine");
450	    materialise(headTree, headPristine, "head", headIndex, true);
451	    linkDependencyDirs(worktree, [headPristine]);
452	    const baselineTestsChanged = !tests || testsChangedSince(headPristine, tests);
453	    const configuredTestsStable = source !== "configured" || !baselineTestsChanged;
454	    const isDeliverableBound = headRun.executedTests && configuredTestsStable &&
455	      isVerifierDeliverableBound(headPristine, changed, command, headRun.output, new Set(deliverables), tests ?? undefined);
456	
457	    // completion_oracle.ts judgeIndependenceImpl, with the base run's usability checked first.
458	    const judgeIndependence = async (): Promise<Independence> => {
459	      if (baseline.failed && baseUnusable) {
460	        return { independent: false, detail: "the verifier did not fail on the base by itself with tests that ran (it was missing, was killed, timed out, or ran no test), so nothing shows the tests failed before the change" };
461	      }
462	      const judged = judgeWithoutCopy(headPristine, command, baseline);
463	      if (judged !== "needs-copy") return judged;
464	      // The change edits test files: run the tests as they were on the base against the head's code.
465	      const copy = prepareBaselineTestsCopy(headPristine, baseline.tests!, baseline.verifier!);
466	      if (!copy) return { independent: false, detail: "the head tree could not be copied to rerun the base's tests against it (it is too large, or holds a link that leaves the tree), so the change's own test edits cannot be set aside" };
467	      try {
468	        const rerun = await execute("base_tests_on_head", copy);
469	        return rerun.success && rerun.executedTests
470	          ? { independent: true, detail: "tests that failed before the change pass after it, with the change's own test edits set aside" }
471	          : { independent: false, detail: "it passes only with tests the change added or edited; the tests as they were before the change still fail" };
472	      } finally {
473	        fs.rmSync(copy, { recursive: true, force: true });
474	      }
475	    };
476	    const independence: Independence | undefined = unboundDetail
477	      ? { independent: false, detail: unboundDetail }
478	      : source === "discovered" && headRun.success && isDeliverableBound ? await judgeIndependence() : undefined;
479	
480	    const evidence: VerificationEvidence = {
481	      status: headRun.success ? "PASSED" : headRun.timedOut ? "TIMED_OUT" : "FAILED",
482	      command,
483	      source,
484	      exitSuccess: headRun.success,
485	      hasExecutedTests: headRun.executedTests,
486	      isDeliverableBound,
487	      filtered: isFilteredVerifierCommand(command),
488	      ...(unboundDetail ? { definitionBound: false as const } : {}),
489	      ...(independence ? { independent: independence.independent, independenceDetail: independence.detail } : {}),
490	      ...(headRun.timedOut ? { deadlineSecs: timeoutSecs } : {}),
491	      outputSha256: sha256(headRun.output),
492	      at: new Date().toISOString(),
493	    };
494	    doc.verification = evidence;
495	    const derived = outcomeFromEvidence(evidence);
496	
497	    // The agent fails a passing verifier when an enforced type-check fails (spine_handlers.ts). This version runs no
498	    // type-check, so where one would be enforced a passing result is withheld rather than reported unchecked.
499	    if (evidence.status === "PASSED" && evidence.hasExecutedTests && typecheckMode(undefined, source === "configured") === "enforce") {
500	      if (typecheckProjects.length) {
501	        const named = [...new Set(typecheckProjects.map((check) => `${check.tool} under ${check.configPath}`))].slice(0, 4).join(", ");
502	        doc.typecheck = { status: "NOT_RUN", detail: `an enforced type-check applies (${named}) and was not run` };
503	        return finish("UNVERIFIED", "TYPECHECK_NOT_RUN", `the verifier passed (${derived.outcome} by tests alone), but a type-check the agent would enforce applies (${named}) and this version of nexus verify does not run type-checks`);
504	      }
505	    }
506	    return finish(derived.outcome, derived.reason, derived.detail);
507	  } catch (error) {
508	    if (error instanceof VerifyUsageError || error instanceof VerifyInterrupted) throw error;
509	    if (error instanceof Stop) return finish("UNVERIFIED", error.reason, error.detail);
510	    if (error instanceof UntrustedCheckoutError) return finish("UNVERIFIED", "UNTRUSTED_CHECKOUT", error.message);
511	    return finish("UNVERIFIED", "INTERNAL_ERROR", `nexus verify could not finish, so nothing was established: ${formatDiagnosticForOutput(error)}`);
512	  } finally {
513	    if (scratch) removeScratch(scratch);
514	  }
515	}
516	
517	/** The verdict as a person reads it. Every repository-controlled string in the result is already terminal-safe. */
518	export function renderVerifyText(result: VerifyJsonResult): string {
519	  const lines: string[] = [];
520	  const row = (label: string, value: string) => lines.push(`  ${label.padEnd(13)}${value}`);
521	  const side = (tree: VerifyTreeRef) => `${tree.ref}${tree.commit ? ` ${tree.commit.slice(0, 12)}` : ""} (tree ${tree.tree.slice(0, 12)})`;
522	  lines.push(`nexus verify: ${result.verdict}${result.reason && result.reason !== result.verdict ? ` (${result.reason})` : ""}`);
523	  if (result.detail) row("why", result.detail);
524	  if (result.base) row("base", side(result.base));
525	  if (result.head) row("head", `${side(result.head)}, ${result.changedFileCount} changed file(s)`);
526	  if (result.verifier) {
527	    const approvals: Record<VerifyVerifierRecord["approval"], string> = { operator_command: "the operator's --verifier", yes: "approved by --yes", digest: "approved by --approve-verifier", none: "NOT APPROVED" };
528	    row("verifier", `${result.verifier.command} (${result.verifier.source}${result.verifier.source === "discovered" ? ` in the base tree: ${result.verifier.evidence}` : ""}; ${approvals[result.verifier.approval]})`);
529	    if (result.verifier.script) row("  script", result.verifier.script.split("\n").join("\n               "));
530	    row("  digest", result.verifier.digest);
531	  }
532	  const phases: Record<VerifyRunRecord["phase"], string> = { base: "base run", head: "head run", base_tests_on_head: "base tests" };
533	  for (const ran of result.runs) {
534	    const how = ran.passed ? "passed" : ran.timedOut ? `timed out after ${result.limits.timeoutSecs}s` : `failed (exit ${ran.exitCode ?? "none"})`;
535	    row(phases[ran.phase], `${how}; ${ran.executedTests ? "tests ran" : "no test ran"}${ran.phase === "base_tests_on_head" ? " (the base's test files against the head's code)" : ""}`);
536	  }
537	  if (result.verifier && result.verifier.approval !== "none" && !result.runs.some((ran) => ran.phase === "head")) row("head run", "not run");
538	  if (result.verification?.independent !== undefined) row("independent", `${result.verification.independent ? "yes" : "no"}: ${result.verification.independenceDetail ?? ""}`);
539	  if (result.verification?.isDeliverableBound !== undefined) {
540	    row("deliverables", result.deliverables.length
541	      ? `${result.deliverables.join(", ")} (${result.verification.isDeliverableBound ? "every one is imported by a test that existed on the base" : "not all shown to be covered by tests that existed on the base"})`
542	      : "none declared (--deliverable-file): the best possible verdict is REGRESSION_FREE");
543	  }
544	  if (result.linkedDependencyDirs.length) row("linked", `${result.linkedDependencyDirs.join(", ")} (from the caller's checkout)`);
545	  row("not run", "type-check, verification-file guard, review");
546	  if (result.typecheck.detail && result.reason === "TYPECHECK_NOT_RUN") row("  type-check", result.typecheck.detail);
547	  if (result.environment.length) row("environment", `set: ${result.environment.join(", ")}`);
548	  const failed = [...result.runs].reverse().find((ran) => ran.phase === "head" && !ran.passed);
549	  if (failed?.outputTail) lines.push("  head output (end; untrusted repository output):", ...failed.outputTail.trimEnd().split("\n").slice(-30).map((line) => `    | ${line}`));
550	  lines.push(`  exit code    ${result.exitCode}`);
551	  return lines.join("\n");
552	}
