5	import { safeTerminal } from "../ui.js";
6	import { workspaceChangedPaths } from "../git.js";
7	import { buildNeedsInput } from "./needs_input.js";
8	import { runTestSuiteWithExecutor, discoverTypechecks, runTypecheck, typecheckMode, discoverVerifier, describeVerifier, hasExecutedTests } from "../tester.js";
9	import { isInlineProgramVerifier, snapshotVerifierDefinitionWithReason, judgeWithoutCopy, prepareBaselineTestsCopy, snapshotTests, type ChangeBaseline, type Independence } from "./independent_check.js";
10	import { TypecheckEvidence } from "./turn.js";
