15	/**
16	 * `askHeadless`: with no operator present, record the decision as a NEEDS_INPUT question (VC-9) instead of only
17	 * refusing. The baseline captures pass false: they run before any change and a refusal there ends nothing.
18	 */
19	export async function ensureVerifierApprovedImpl(this: any, command: string, confirmHandler?: ConfirmHandler, origin?: string, binding?: string, askHeadless = true): Promise<boolean> {
20	  const isTrusted = isWorkspaceTrusted(this.config.workspace, this.isReadOnly());
21	  const mode = this.getApprovalMode();
22	  const policyContext: PolicyContext = {
23	    mode,
24	    trusted: isTrusted,
25	    sandbox: this.config.sandbox,
26	    approvedEgressOrigins: this.approvedEgressOrigins,
27	    fullAccess: Boolean(this.config.fullAccess) && !this.isReadOnly(),
28	  };
29	
30	  if (!this.approvalPolicy.requiresDecision("exec", policyContext)) {
31	    return true;
32	  }
33	
34	  const desc = describeVerifier(this.config.workspace, command);
35	  const verifierCmd = desc?.command || command;
36	  const baseDigest = desc?.digest || createHash("sha256").update(verifierCmd).digest("hex");
37	  const digest = binding ? createHash("sha256").update(`${baseDigest}\n${binding}`).digest("hex") : baseDigest;
38	  const cacheKey = `${this.config.workspace}:${verifierCmd}:${digest}`;
39	
40	  if (this.approvedVerifiers.has(cacheKey)) {
41	    return true;
42	  }
43	
44	  const onConfirm = confirmHandler ?? this.activeTurn?.onConfirm;
45	  if (!onConfirm) {
46	    if (!askHeadless) return false;
47	    const decision = this.headlessDecision(buildNeedsInput(
48	      "verifier_approval",
49	      `Run ${verifierCmd.slice(0, 160)} as the verifier${origin ? ` (${origin.slice(0, 120)})` : ""}?`,
50	      { command: verifierCmd.slice(0, 200), digest: digest.slice(0, 16) },
51	      verifierCmd,
52	      digest,
53	    ));
54	    if (decision !== "approve") return false;
55	    this.approvedVerifiers.add(cacheKey);
56	    return true;
57	  }
58	
59	  const approved = await onConfirm("verifier", {
60	    command: verifierCmd,
61	    script: desc?.script,
62	    detail: origin ? `${origin}${desc?.evidence ? `\n${desc.evidence}` : ""}` : desc?.evidence,
63	    digest,
64	  });
65	
66	  if (approved) {
67	    this.approvedVerifiers.add(cacheKey);
68	    return true;
69	  }
70	  return false;
71	}
