249	export async function judgeIndependenceImpl(this: any, command: string, deadlineSecs: number, confirmHandler?: ConfirmHandler): Promise<Independence> {
250	  const judged = judgeWithoutCopy(this.config.workspace, command, this.changeBaseline);
251	  if (judged !== "needs-copy") return judged;
252	  const approved = await this.ensureVerifierApproved(command, confirmHandler);
253	  if (!approved) return { independent: false, detail: "verifier execution was not approved" };
254	  // Nexus edited test files: run the tests as they were before the change against the changed code.
255	  const dir = prepareBaselineTestsCopy(this.config.workspace, this.changeBaseline!.tests!, this.changeBaseline!.verifier!);
256	  if (!dir) return { independent: false, detail: "the workspace is too large to rerun the pre-change tests without Nexus's own test edits" };
257	  try {
258	    this.activity("verifying", { tool: `${command} (tests as they were before the change)` });
259	    const quoted = `'${dir.replace(/'/g, `'\\''`)}'`;
260	    const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: `cd ${quoted} && ${c}`, timeout_secs: deadlineSecs }), command);
261	    return run.success && hasExecutedTests(run.rawOutput || "")
262	      ? { independent: true, detail: "tests that failed before the change pass after it, with Nexus's own test edits set aside" }
263	      : { independent: false, detail: "it passes only with tests Nexus wrote or edited; the tests as they were before the change still fail" };
264	  } finally {
265	    fs.rmSync(dir, { recursive: true, force: true });
266	  }
267	}
