269	export async function runRequirementVerifierImpl(this: any, requirement: { id: string; verifierSource?: string }, command: string): Promise<string | undefined> {
270	  const ledger = this.objective;
271	  const state = this.verifierState();
272	  if (!ledger || !state || priorAttempt(ledger, command, state, requirement.id)) return undefined;
273	  const onConfirm = this.activeTurn?.onConfirm;
274	  const origin = `${requirement.verifierSource === "operator" ? "operator-declared" : "model-declared"} verifier for ${requirement.id}: ${command}`;
275	  if (!(await this.ensureVerifierApproved(command, onConfirm, origin))) {
276	    return `${requirement.id}: verifier execution was not approved${onConfirm ? "" : " (it requires operator approval and no operator is present)"}`;
277	  }
278	  const deadlineSecs = this.config.verifierTimeoutSecs ?? DEFAULT_VERIFIER_TIMEOUT_SECS;
279	  this.activity("verifying", { tool: command });
280	  const run = await runTestSuiteWithExecutor(this.config.workspace, (c) => this.bridge.executeTool("run_command", { command: c, timeout_secs: deadlineSecs }), command);
281	  // The state after the run: a verifier that writes build output must still be able to verify what it produced.
282	  const after = this.verifierState();
283	  if (after) {
284	    recordAttempt(ledger, {
285	      command,
286	      ...after,
287	      status: run.success ? "PASSED" : run.timedOut ? "TIMED_OUT" : "FAILED",
288	      requirementId: requirement.id,
289	      ...(run.success ? {} : { failedCheck: failedCheckFrom(run.rawOutput || ""), ...attemptEvidence(run.rawOutput || "", run.exitCode, { timedOut: run.timedOut, executorFailed: run.executorFailed }) }),
290	    });
291	  }
292	  this.turnVerifierRuns.push({ command, phase: "completion", passed: run.success });
293	  return undefined;
294	}
