export type TypecheckMode = "off" | "record" | "enforce";

/** NEXUS_TYPECHECK (off | enforce) overrides the configured mode; a configured verifier makes the check record-only by default. */
export function typecheckMode(configured: TypecheckMode | undefined, hasConfiguredVerifier: boolean): TypecheckMode {
  const env = process.env.NEXUS_TYPECHECK?.trim().toLowerCase();
  if (env === "off" || env === "enforce") return env;
  return configured ?? (hasConfiguredVerifier ? "record" : "enforce");
}

export interface DiscoveredTypecheck {
  tool: "tsc" | "cargo" | "go" | "pyright" | "mypy";
  /** The tool is on no search path the check would use here: reported UNAVAILABLE without running or asking approval. */
  missingTool?: boolean;
  /** Prints the tool version; run as its own call so no shell operator is assumed. */
  probe: string;
  command: string;
  /** Workspace-relative configuration file the check ran under. */
  configPath: string;
  /** Workspace-relative project directory, including for projects nested inside a monorepo. */
  projectRoot?: string;
  configSha256: string;
  /** Hash of the resolved tool launcher, so an approval binds to the binary that runs. */
  toolSha256?: string;
  /** Set when the configuration is not one a type-check can stand for (e.g. a solution-style tsconfig). */
  skipReason?: string;
  /** Discovery hit a hard safety cap, so the set of project checks is incomplete. */
  discoveryIncomplete?: boolean;
}

const sha256File = (file: string): string | undefined => {
  try {
    return createHash("sha256").update(fs.readFileSync(fs.realpathSync(file))).digest("hex");
  } catch {
    return undefined;
  }
};

function resolveOnPath(name: string): string | undefined {
  for (const dir of (process.env.PATH ?? "").split(path.delimiter)) {
    if (!dir) continue;
    const candidate = path.join(dir, name);
    try {
      fs.accessSync(candidate, fs.constants.X_OK);
      return candidate;
    } catch {}
  }
  return undefined;
}

const shellQuote = (value: string) => `'${value.replaceAll("'", "'\\''")}'`;
const shellPath = (value: string) => /^[A-Za-z0-9_./-]+$/.test(value) ? value : shellQuote(value);

/** Discover one check per configured project, including nested packages in a monorepo. */
export function discoverTypechecks(workspace: string): DiscoveredTypecheck[] {
  const root = path.resolve(workspace);
  const result: DiscoveredTypecheck[] = [];
  const ignored = new Set([".git", "node_modules", "target", "dist", "build", "coverage", ".venv", "venv", "vendor"]);
  const queue = [root];
  const seen = new Set<string>();
  // Bound repository-controlled traversal. If this limit is reached, callers get all checks found so far;
  // the explicit cap prevents a generated or hostile workspace from turning verification into an unbounded scan.
  const maxDirectories = 20_000;
  const maxChecks = 32;
  let capped = false;
  while (queue.length && seen.size < maxDirectories) {
    const project = queue.shift()!;
    let real: string;
    try { real = fs.realpathSync(project); } catch { continue; }
    if (seen.has(real) || (real !== root && !real.startsWith(`${root}${path.sep}`))) continue;
    seen.add(real);
    const checks = discoverTypechecksAtRoot(root, project);
    if (checks.length) {
      const available = maxChecks - result.length;
      result.push(...checks.slice(0, available));
      if (checks.length > available) { capped = true; break; }
    }
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(project, { withFileTypes: true }); } catch { continue; }
    for (const entry of entries) {
      if (!entry.isDirectory() || ignored.has(entry.name)) continue;
      queue.push(path.join(project, entry.name));
    }
  }
  if (queue.length) capped = true;
  if (capped) result.push({ tool: "tsc", probe: "", command: "<bounded project discovery>", configPath: "<workspace project scan>", configSha256: "", skipReason: "workspace contains more projects than the bounded type-check discovery limit permits", discoveryIncomplete: true });
  return result;
}

/** Compatibility helper for callers that need the workspace-root project's check. */
export function discoverTypecheck(workspace: string): DiscoveredTypecheck | null {
  const root = path.resolve(workspace);
  return discoverTypecheckAtRoot(root, root) ?? discoverTypecheckAtRoot(root, path.join(root, "core"));
}

function discoverTypecheckAtRoot(root: string, project: string): DiscoveredTypecheck | null {
  return discoverTypechecksAtRoot(root, project)[0] ?? null;
}

function discoverTypechecksAtRoot(root: string, project: string): DiscoveredTypecheck[] {
  const projectRelative = path.relative(root, project).split(path.sep).join("/");
  const prefix = projectRelative ? `cd ${shellQuote(projectRelative)} && ` : "";
  const read = (rel: string): string | null => {
    try {
      return fs.readFileSync(path.join(project, rel), "utf-8");
    } catch {
      return null;
    }
  };
  status: TypecheckStatus;
  exitCode: number | null;
  version?: string;
  output: string;
  errorCount?: number;
  firstDiagnostics?: string[];
  /** Errors not present in the baseline run (only when a baseline was supplied). */
  introducedCount?: number;
  /** Every located error, as `file<NL>message` signatures; what a baseline stores. */
  signatures?: string[];
}

export type TimedExecutor = (command: string, timeoutSecs: number) => Promise<{ success: boolean; output: string; error?: string; timedOut?: boolean }>;

/** A located error's identity across runs: the file relative to the workspace and the message, never the line (edits move it). */
export function typecheckSignatures(check: Pick<DiscoveredTypecheck, "configPath">, output: string, workspace: string): string[] {
  const root = path.resolve(workspace);
  const bases = [root, path.resolve(root, path.dirname(check.configPath))];
  return parseTypecheckDiagnostics(output).located.map(({ file, text }) => {
    const abs = path.isAbsolute(file) ? file : path.resolve(bases[1], file);
    const rel = path.relative(root, abs);
    return `${rel.startsWith("..") ? file : rel}\n${text}`;
  });
}

/**
 * Decide what a non-zero check means. It blocks (FAILED) when an error is located in a file the candidate modified, or,
 * given a `baseline` (the signatures present before the change), when any error is new (a caller broken in an untouched
 * file). Errors only in untouched files that the baseline already had are PREEXISTING; output that cannot be attributed
 * is ENVIRONMENT.
 */
export function classifyTypecheck(
  check: Pick<DiscoveredTypecheck, "tool" | "configPath">,
  output: string,
  workspace: string,
  modified: ReadonlySet<string>,
  baseline?: ReadonlySet<string>,
): { status: "FAILED" | "ENVIRONMENT" | "PREEXISTING"; diagnostics: TypecheckDiagnostics; introducedCount?: number; signatures: string[] } {
  const diagnostics = parseTypecheckDiagnostics(output);
  // No located error: configuration (TS5xxx/TS6xxx), missing type packages, dependency resolution, offline or lockfile
  // failures. These say the check could not run here, not that the candidate broke it.
  if (diagnostics.files.length === 0) return { status: "ENVIRONMENT", diagnostics, signatures: [] };
  const signatures = typecheckSignatures(check, output, workspace);
  const introduced = baseline ? signatures.filter((sig) => !baseline.has(sig)).length : undefined;
  const root = path.resolve(workspace);
  const bases = [root, path.resolve(root, path.dirname(check.configPath))];
  const real = (f: string) => {
    try {
      return fs.realpathSync(f);
    } catch {
      return f;
    }
  };
  const touched = new Set<string>();
  for (const m of modified) {
    touched.add(path.resolve(m));
    touched.add(real(m));
  }
  const hit = diagnostics.files.some((f) => bases.some((b) => {
    const abs = path.resolve(b, f);
    return touched.has(abs) || touched.has(real(abs));
  }));
  return { status: hit || (introduced ?? 0) > 0 ? "FAILED" : "PREEXISTING", diagnostics, signatures, ...(introduced !== undefined ? { introducedCount: introduced } : {}) };
}

export async function runTypecheck(
  check: DiscoveredTypecheck,
  execute: TimedExecutor,
  workspace: string,
  modified: ReadonlySet<string>,
  budgetSecs: number,
  baseline?: ReadonlySet<string>,
): Promise<TypecheckRun> {
  const PROBE_SECS = 30;
  let version: string | undefined;
  if (check.missingTool) return { status: "UNAVAILABLE", exitCode: null, output: `${check.tool} is not installed here` };
  try {
    const probe = parseExecution(await execute(check.probe, Math.min(PROBE_SECS, budgetSecs)));
    if (!probe.succeeded) return { status: probe.exitCode === 126 || probe.exitCode === 127 ? "UNAVAILABLE" : "ENVIRONMENT", exitCode: probe.exitCode ?? null, output: probe.rawOutput };
    const line = probe.rawOutput.split("\n")[0]?.trim() ?? "";
    if (/\d+\.\d+/.test(line)) version = line.slice(0, 100);
  } catch (error: any) {
    return { status: "ENVIRONMENT", exitCode: null, output: String(error?.message ?? error) };
  }
  let run: ReturnType<typeof parseExecution>;
  try {
    run = parseExecution(await execute(check.command, budgetSecs));
  } catch (error: any) {
    return { status: "ENVIRONMENT", exitCode: null, version, output: String(error?.message ?? error) };
  }
  const base = { exitCode: run.exitCode ?? null, version, output: run.rawOutput };
  if (run.timedOut) return { ...base, status: "TIMED_OUT" };
  if (run.succeeded) return { ...base, status: "PASSED" };
  if (run.exitCode === undefined || run.exitCode === null || run.exitCode === 126 || run.exitCode === 127) return { ...base, status: "ENVIRONMENT" };
  const { status, diagnostics, introducedCount, signatures } = classifyTypecheck(check, run.rawOutput, workspace, modified, baseline);
  return {
    ...base,
    status,
    errorCount: diagnostics.errorCount,
    firstDiagnostics: diagnostics.first,
    signatures,
    ...(introducedCount !== undefined ? { introducedCount } : {}),
  };
}

