/** Python is checked only when the project configures pyright or mypy; the tool comes from the project's virtualenv or PATH. */
function discoverPythonTypechecks(root: string, read: (rel: string) => string | null, sha: (text: string) => string): DiscoveredTypecheck[] {
  const pyproject = read("pyproject.toml") ?? "";
  const setupCfg = read("setup.cfg") ?? "";
  const candidates: Array<{ tool: "pyright" | "mypy"; configPath: string; text: string }> = [];
  const pyrightJson = read("pyrightconfig.json");
  if (pyrightJson !== null) candidates.push({ tool: "pyright", configPath: "pyrightconfig.json", text: pyrightJson });
  if (/^\[tool\.pyright\]/m.test(pyproject)) candidates.push({ tool: "pyright", configPath: "pyproject.toml", text: pyproject });
  for (const rel of ["mypy.ini", ".mypy.ini"]) {
    const text = read(rel);
    if (text !== null) candidates.push({ tool: "mypy", configPath: rel, text });
  }
  if (/^\[tool\.mypy\]/m.test(pyproject)) candidates.push({ tool: "mypy", configPath: "pyproject.toml", text: pyproject });
  if (/^\[mypy\]/m.test(setupCfg)) candidates.push({ tool: "mypy", configPath: "setup.cfg", text: setupCfg });
  return candidates.map((candidate) => {
    const local = [".venv/bin", "venv/bin"].map((d) => path.join(root, d, candidate.tool)).find((f) => fs.existsSync(f));
    const resolved = local ?? resolveOnPath(candidate.tool);
    const launcher = local ? `./${path.relative(root, local)}` : candidate.tool;
    return {
      tool: candidate.tool,
      probe: `${launcher} --version`,
      command: candidate.tool === "mypy" ? `${launcher} .` : launcher,
      configPath: candidate.configPath,
      configSha256: sha(candidate.text),
      toolSha256: sha256File(resolved ?? ""),
      ...(resolved ? {} : { missingTool: true }),
    };
  });
}

export interface TypecheckDiagnostics {
  errorCount: number;
  /** Files (as printed by the tool) that carry at least one located error. */
  files: string[];
  /** Error codes of diagnostics with no source location (configuration errors). */
  unlocatedCodes: string[];
  first: string[];
  /** Every located error as file (as printed) and the message without its line and column. */
  located: Array<{ file: string; text: string }>;
}

/** tsc `path(line,col): error TSxxxx` and `path:line:col - error TSxxxx`; cargo `error...` followed by `--> path:line:col`. */
/** Terminal escape sequences (CSI, such as colours, and OSC): presentation only, never part of a diagnostic. */
const TYPECHECK_ANSI = /\u001b(?:\[[0-9;?]*[ -/]*[@-~]|\][^\u0007\u001b]*(?:\u0007|\u001b\\))/g;

export function parseTypecheckDiagnostics(output: string): TypecheckDiagnostics {
  const files = new Set<string>();
  const unlocatedCodes: string[] = [];
  const first: string[] = [];
  const located: Array<{ file: string; text: string }> = [];
  let errorCount = 0;
  let cargoError: string | undefined;
  const note = (line: string, file?: string, text?: string) => {
    errorCount++;
    if (file !== undefined) located.push({ file, text: (text ?? line).trim().slice(0, 240) });
    if (first.length < 5) first.push(line.trim().slice(0, 240));
  };
  // A type-checker colours its output when the environment asks for it (FORCE_COLOR, a pretty default): the file, line
  // and column are then wrapped in escape sequences and no pattern below would match, so a failing check would be read
  // as "could not run" (ENVIRONMENT) and stop blocking. Colour carries no meaning here; it is removed first.
  for (const raw of output.replace(TYPECHECK_ANSI, "").split("\n")) {
    const line = raw.replace(/\r$/, "");
    const tsc = line.match(/^(.+?)\((\d+),(\d+)\): error (TS\d+):/) ?? line.match(/^(.+?):(\d+):(\d+) - error (TS\d+):/);
    if (tsc) {
      files.add(tsc[1]);
      note(line, tsc[1], line.slice(line.indexOf(" error ") + 1));
      continue;
    }
    // go: `path.go:12:5: message` (and `vet: path.go:12:5: message`); pyright: `  /abs/f.py:12:5 - error: message`; mypy: `f.py:12: error: message`
    const other = line.match(/^(?:vet: )?(\S.*?\.go):(\d+):(\d+): (.+)$/) ?? line.match(/^\s*(.+?\.pyi?):(\d+):(\d+) - error: (.+)$/) ?? line.match(/^(.+?\.pyi?):(\d+)(?::\d+)?: error: (.+)$/);
    if (other) {
      files.add(other[1]);
      note(line, other[1], other[other.length - 1]);
      continue;
    }
    const bare = line.match(/^error (TS\d+):/);
    if (bare) {
      unlocatedCodes.push(bare[1]);
      note(line);
      continue;
    }
    const header = line.match(/^(error|warning)(?:\[\w+\])?:/);
    if (header) {
      cargoError = header[1] === "error" ? line : undefined;
      continue;
    }
    const arrow = line.match(/^\s*--> (.+?):\d+:\d+/);
    if (arrow && cargoError) {
      files.add(arrow[1]);
      note(cargoError, arrow[1]);
      cargoError = undefined;
    }
  }
  return { errorCount, files: [...files], unlocatedCodes, first, located };
}

/** UNAVAILABLE: the tool is not installed here, so nothing was checked (never a pass). */
export type TypecheckStatus = "PASSED" | "FAILED" | "TIMED_OUT" | "ENVIRONMENT" | "PREEXISTING" | "UNAVAILABLE";

export interface TypecheckRun {
  status: TypecheckStatus;

/** Unwrap the runner's envelope; a killed or timed-out command has `exit_code: null`. */
export function parseExecution(result: { success: boolean; output: string; error?: string; timedOut?: boolean }): ParsedExecution {
  let succeeded = false;
  let timedOut = result.timedOut === true;
  let exitCode: number | null | undefined;
  let rawOutput = [result.output, result.error].filter(Boolean).join("\n");
  if (result.success) {
    try {
      const execution = JSON.parse(result.output);
      if (execution && typeof execution === "object" && "exit_code" in execution) {
        timedOut = execution.timed_out === true;
        exitCode = typeof execution.exit_code === "number" ? execution.exit_code : null;
        succeeded = exitCode === 0 && !timedOut;
        rawOutput = [execution.stdout, execution.stderr, result.error].filter(Boolean).join("\n");
      }
    } catch {
      // Unknown executor output is not proof that the command exited successfully.
    }
  }
  return { succeeded, timedOut, exitCode, rawOutput };
}

/** Execute test discovery or an explicit verifier through the caller's mutation boundary. */
export async function runTestSuiteWithExecutor(
  workspace: string,
  execute: TestCommandExecutor,
  commandOverride?: string,
): Promise<TestRunResult> {
  const command = commandOverride?.trim() || discoverVerifier(workspace)?.command || "none";
  if (command === "none") return summarizeTestRun("none", false, "no verifier: no verification command is configured or discovered in this workspace.");
  try {
    const result = await execute(command);
    const { succeeded: commandSucceeded, timedOut, exitCode: parsedExit, rawOutput } = parseExecution(result);
    const exitCode = typeof parsedExit === "number" ? parsedExit : undefined;
    const summary = summarizeTestRun(command, commandSucceeded, rawOutput);
    const withExit = {
      ...summary,
      ...(exitCode === undefined ? {} : { exitCode }),
      ...(!result.success ? { executorFailed: true } : {}),
    };
    return timedOut ? { ...withExit, success: false, timedOut: true } : withExit;
  } catch (error: any) {
    return { ...summarizeTestRun(command, false, error?.message || "Verification command execution failed."), executorFailed: true };
  }
}
