40	function writeFiles(repo: string, files: Record<string, string>): void {
41	  for (const [name, content] of Object.entries(files)) {
42	    fs.mkdirSync(path.dirname(path.join(repo, name)), { recursive: true });
43	    fs.writeFileSync(path.join(repo, name), content);
44	  }
45	}
