47	/** Commits `files` on top of the current commit and returns the new commit. */
48	function commit(repo: string, files: Record<string, string>, author = "t <t@t.invalid>"): string {
49	  writeFiles(repo, files);
50	  git(repo, "add", "-A");
51	  git(repo, "-c", "user.name=committer", "-c", "user.email=c@c.invalid", "commit", "-q", "--author", author, "-m", "change");
52	  return head(repo);
53	}
