55	/** A digest of everything under `root`: every file's bytes, every link's target, every directory, `.git` included. */
56	function treeDigest(root: string): string {
57	  const hash = createHash("sha256");
58	  const walk = (dir: string) => {
59	    for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
60	      const full = path.join(dir, entry.name);
61	      const name = path.relative(root, full);
62	      if (entry.isSymbolicLink()) hash.update(`L\0${name}\0${fs.readlinkSync(full)}\0`);
63	      else if (entry.isDirectory()) { hash.update(`D\0${name}\0`); walk(full); }
64	      else hash.update(`F\0${name}\0${fs.statSync(full).mode}\0`).update(fs.readFileSync(full)).update("\0");
65	    }
66	  };
67	  walk(root);
68	  return hash.digest("hex");
69	}
