73	/**
74	 * Runs `nexus verify <args>` (the source entry) with a throwaway HOME, its own temp directory and no operator
75	 * environment. `leftovers`: what verify left in that temp directory (its scratch trees and verifier output files).
76	 */
77	function runCli(args: string[], extraEnv: Record<string, string> = {}): Promise<CliRun> {
78	  const env = { ...process.env };
79	  for (const key of Object.keys(env)) if (/^(LOCAL_LLM_|LOCAL_HARNESS_|NEXUS_|GIT_)/.test(key) || key === "NODE_TEST_CONTEXT") delete env[key];
80	  const home = makeHome();
81	  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-verify-test-tmp-"));
82	  return new Promise((resolve, reject) => {
83	    const child = spawn(process.execPath, ["--import", "tsx", "src/index.ts", "verify", ...args], {
84	      cwd: CLI_DIR,
85	      env: { ...env, HOME: home, TMPDIR: tmp, XDG_CONFIG_HOME: path.join(home, ".config"), XDG_DATA_HOME: path.join(home, ".local", "share"), XDG_STATE_HOME: path.join(home, ".local", "state"), XDG_CACHE_HOME: path.join(home, ".cache"), ...extraEnv },
86	      stdio: ["ignore", "pipe", "pipe"],
87	    });
88	    let stdout = "";
89	    let stderr = "";
90	    child.stdout!.on("data", (chunk) => (stdout += chunk));
91	    child.stderr!.on("data", (chunk) => (stderr += chunk));
92	    child.on("error", reject);
93	    child.on("close", (code) => {
94	      const leftovers = fs.readdirSync(tmp).filter((name) => name.startsWith("nexus-"));
95	      fs.rmSync(tmp, { recursive: true, force: true });
96	      fs.rmSync(home, { recursive: true, force: true });
97	      resolve({ code, stdout, stderr, leftovers });
98	    });
99	  });
100	}
