102	/** What a consumer does: stdout is exactly one JSON document, `schema_version` first, `exitCode` the process exit code. */
103	function consume(run: CliRun): any {
104	  let doc: any;
105	  try {
106	    doc = JSON.parse(run.stdout);
107	  } catch {
108	    assert.fail(`stdout is not one JSON document: ${run.stdout.slice(0, 200)}\nstderr: ${run.stderr.slice(0, 400)}`);
109	  }
110	  assert.equal(run.stdout, `${JSON.stringify(doc, null, 2)}\n`, "nothing but the document on stdout");
111	  assert.equal(Object.keys(doc)[0], "schema_version");
112	  assert.equal(doc.schema_version, VERIFY_RESULT_SCHEMA_VERSION);
113	  assert.equal(doc.exitCode, run.code, "exitCode repeats the process exit code");
114	  assert.deepEqual(run.leftovers, [], "no scratch directory is left behind");
115	  return doc;
116	}
