118	/** A result document: the verdict, the exit code and the reason agree with the contract's tables, and the ingredients this version does not run say so. */
119	function consumeResult(run: CliRun): any {
120	  const doc = consume(run);
121	  assert.equal(doc.verdict, verifyVerdictFor(doc.reason), `${doc.verdict}/${doc.reason}: ${doc.detail}`);
122	  assert.equal(doc.exitCode, verifyExitCode(verifyExitNameFor(doc.reason)));
123	  assert.equal(doc.verdict === "VERIFIED", run.code === 0, "exit 0 if and only if VERIFIED");
124	  assert.equal(doc.verdict === "VERIFIED", doc.outcome === "VERIFIED");
125	  for (const ingredient of ["typecheck", "guard", "review"]) assert.equal(doc[ingredient].status, "NOT_RUN", ingredient);
126	  return doc;
127	}
