131	/** Runs `check` on fresh repositories built from the given files and removes them afterwards. */
132	async function withRepos<T>(files: Array<Record<string, string>>, check: (...repos: string[]) => Promise<T>): Promise<T> {
133	  const repos = files.map((set) => makeRepo(set));
134	  try {
135	    return await check(...repos);
136	  } finally {
137	    for (const repo of repos) fs.rmSync(repo, { recursive: true, force: true });
138	  }
139	}
