// ---- The verification-file guard ----

const SKIPPED = TEST_FULL.replace('test("double"', 'test.skip("double"');
const finding = (result: VerifyJsonResult, file: string) => result.guard.findings.find((item) => item.path === file);
const approving = (...files: string[]): VerifyOperatorContext => ({ ...OPERATOR, approvedVerificationEdits: files });

test("guard: a weakened test (assertion removed, .skip added, an early exit, the file deleted) is BLOCKED with the weakening named; approved, it is no longer BLOCKED and still not VERIFIED", { timeout: 120_000 }, async () => {
  const cases: Array<{ name: string; files: Record<string, string | null>; kind: string; weakening: string[]; approved: Array<string | number | undefined> }> = [
    // The bug stays and the failing test goes: with approval the verdict is what the base's tests show.
    { name: "assertion removed", files: BAD, kind: "modified", weakening: ["fewer-assertions"], approved: ["REGRESSION_FREE", "REGRESSION_FREE", "REGRESSION_FREE", 2] },
    // A real fix beside the weakening: the base's tests pass on the head, and approval still does not make it VERIFIED.
    { name: ".skip added", files: { ...GOOD, [TEST_FILE]: SKIPPED }, kind: "modified", weakening: ["skipped"], approved: ["REGRESSION_FREE", "REGRESSION_FREE", "REGRESSION_FREE", 2] },
    { name: "early exit added", files: { ...GOOD, [TEST_FILE]: `${TEST_HEAD}process.exit(0);\ntest("add", () => assert.equal(add(2, 3), 5));\n` }, kind: "modified", weakening: ["neutered"], approved: ["REGRESSION_FREE", "REGRESSION_FREE", "REGRESSION_FREE", 2] },
    { name: "test file deleted", files: { ...GOOD, [TEST_FILE]: null }, kind: "deleted", weakening: ["removed"], approved: ["UNVERIFIED", "UNVERIFIED", "NO_TESTS_EXECUTED", 2] },
  ];
  for (const c of cases) {
    const blocked = await verifyChangeTo(BASE_FILES, c.files);
    assert.deepEqual(summary(blocked), ["BLOCKED", "UNVERIFIED", "VERIFICATION_EDIT_BLOCKED", 3], `${c.name}: ${blocked.detail}`);
    assert.deepEqual(blocked.guard.status, "BLOCKED", c.name);
    assert.deepEqual(finding(blocked, TEST_FILE), { path: TEST_FILE, class: "test_file", kind: c.kind, weakening: c.weakening, requiresApproval: true, approved: false }, c.name);
    assert.ok(blocked.detail?.includes(`${TEST_FILE} (test_file, ${c.kind}: ${c.weakening.join(", ")})`), `${c.name}: ${blocked.detail}`);
    assert.match(blocked.detail ?? "", /--approve-verification-edit <path>/, c.name);

    const approved = await verifyChangeTo(BASE_FILES, c.files, approving(TEST_FILE));
    assert.deepEqual(summary(approved), c.approved, `${c.name}: ${approved.detail}`);
    assert.equal(approved.guard.status, "CLEAR", c.name);
    assert.deepEqual(finding(approved, TEST_FILE), { ...finding(blocked, TEST_FILE), approved: true }, c.name);
    assert.deepEqual(approved.approvedVerificationEdits, [TEST_FILE]);
  }
  // The second case is the one only the approval rule holds back: the base's tests, rerun against the head, pass.
  const skip = await verifyChangeTo(BASE_FILES, cases[1].files, approving(TEST_FILE));
  assert.equal(skip.verification?.independent, true);
  assert.equal(skip.verification?.isDeliverableBound, true);
  assert.match(skip.detail ?? "", /lets the result be reported; it does not make the change verified/);
});

test("guard: a plain edit of a test and a new test file are recorded and do not block; an edit to package.json outside its scripts is no finding", { timeout: 120_000 }, async () => {
  const extraTest = 'import test from "node:test";\nimport assert from "node:assert/strict";\nimport { double } from "../src/math.js";\ntest("double of zero", () => assert.equal(double(0), 0));\n';
  const added = await verifyChangeTo(BASE_FILES, { ...GOOD, "test/extra.test.mjs": extraTest });
  assert.deepEqual(added.guard, { status: "CLEAR", mode: "approve", policySource: "default", findings: [{ path: "test/extra.test.mjs", class: "test_file", kind: "added", requiresApproval: false, approved: false }], complete: true });
  assert.deepEqual(summary(added), ["VERIFIED", "VERIFIED", undefined, 0], added.detail);

  const edited = await verifyChangeTo(BASE_FILES, { ...GOOD, [TEST_FILE]: `${TEST_FULL}test("double of three", () => assert.equal(double(3), 6));\n` });
